  function privacyPage() { const d = draft('privacy'); return frame('应用隐私', 'App privacy', T('分别选择内容、活动或不记录；保存后用于后续记录。', 'Choose content, activity or off for each app. Saved choices apply to future records.'), '<div class="fields">' + select('privacy', 'defaultMode', '未单独设置的应用', 'Apps without a specific rule', modes()) + '<section class="ns-app-rules"><h2>' + T('单独设置的应用', 'Per-app rules') + '</h2>' + d.rules.map((r, i) => '<div class="ns-app-rule"><div><strong>' + E(r.name) + '</strong><small>' + E(r.id) + '</small></div><select class="field-input" aria-label="' + E(T(r.name + ' 的记录级别', 'Collection level for ' + r.name)) + '" data-ns-app-index="' + i + '">' + modes().map(([v, l]) => '<option value="' + v + '" ' + (r.mode === v ? 'selected' : '') + '>' + l + '</option>').join('') + '</select>' + A('移除', 'Remove', 'app-remove', 'data-index="' + i + '"', 'text') + (android() ? A('页面字段', 'Page fields', 'app-format', 'data-app="' + E(r.id) + '"', 'text') : '') + '</div>').join('') + A('选择已安装的应用', 'Choose an installed app', 'app-pick', '', 'subtle') + disclosure('manual-app', '手动输入应用 ID', 'Enter an app ID manually', '<label class="field"><span>' + T(android() ? 'Package ID' : 'Bundle ID', android() ? 'Package ID' : 'Bundle ID') + '</span><input id="ns-manual-app" class="field-input" autocomplete="off" placeholder="' + (android() ? 'com.example.app' : 'com.example.App') + '"></label>' + A('添加为仅活动', 'Add as activity only', 'app-add-manual')) + '</section></div>' + disclosure('privacy-meaning', '记录级别与设备信息', 'Collection levels and device information', '<p>' + T('仅活动只保留应用身份与采样时间，不读标题、正文或截图。不记录不产生该应用记录。出现未知或混合窗口时按隐私规则停止，不会回退截图绕过拒绝。', 'Activity only retains app identity and sample time, without titles, bodies or screenshots. Off creates no record. Unknown or mixed windows fail closed under the privacy rules; screenshot fallback never bypasses rejection.') + '</p>' + check('privacy', 'metadata', '附带设备与采样元数据', 'Include device and capture metadata', T('可含系统版本、型号、语言、时区、电量与可用空间；平台未提供的值留空。不包含序列号、SSID 或定位。只影响未来记录，文件的大小与时间独立保留。', 'May include OS, model, language, timezone, battery and free space; unavailable fields stay empty. No serial number, SSID or location. Future records only; file size and time are independent.'))) + footer('privacy') + '<div class="ns-menu ns-related">' + menuRow('页面内容采集', 'Page extraction', T('平台支持的采集模式与明确规则', 'Supported modes and explicit page rules'), 'settings/native-pages') + menuRow('固定遮挡区域', 'Fixed screen masks', T('在文字审查与保存前应用', 'Apply before text review and persistence'), 'settings/native-masks') + menuRow('文字审查与待复核', 'Text review and held records', T('精确文字规则及失败处理', 'Exact text rules and failure handling'), 'settings/native-gate') + menuRow('系统权限', 'System permissions', T('查看授权状态并返回原任务', 'Inspect authorization and return to your task'), 'settings/native-permissions') + '</div>'); }
  function pagesPage() { const options = android() ? [['screen_only', T('仅截图', 'Screenshots only')], ['ui_preferred', T('页面优先，完整时不截图', 'Page preferred; skip screenshot when complete')]] : [['screen_only', T('仅截图', 'Screenshots only')], ['hybrid', T('页面与截图', 'Page and screenshot')], ['ui_preferred', T('页面优先，完整时不截图', 'Page preferred; skip screenshot when complete')], ['page_only', T('仅页面，不回退截图', 'Page only; no screenshot fallback')]]; return frame('页面内容采集', 'Page extraction', T('只在明确授权的应用及页面读取可见内容。', 'Read visible content only in explicitly authorized apps and pages.'), '<div class="fields">' + select('pages', 'mode', '采集模式', 'Extraction mode', options, T('隐私拒绝不会触发截图回退。Android 投屏只支持截图。', 'Privacy rejection never triggers screenshot fallback. Android projection supports screenshots only.')) + '</div>' + disclosure('page-json', '高级：页面规则', 'Advanced: page rules', textarea('pages', 'rules', '页面规则 JSON', 'Page rule JSON', T('精确配置应用、页面和节点；规则不会授予内容权限。', 'Explicit app, page and node configuration; rules do not grant content permission.'), 7) + (!android() ? A('载入实验规则', 'Load experimental rules', 'page-builtins', '', 'subtle') + '<p class="small muted">' + T('仅通过生成样本验证；配置匹配不表示实际应用已验证。', 'Validated only with generated fixtures; a configuration match is not live-app verification.') + '</p>' : L('按应用版本配置文章 / 商品字段', 'Configure article or product fields by app version', 'settings/native-app-format'))) + footer('pages'), 'settings/native-privacy'); }
  function appFormatPage() { return frame('应用页面字段', 'App page fields', T('每个应用版本单独保存。配置不会开启内容采集。', 'Save separately for each app version. Configuration does not enable content collection.'), '<div class="fields">' + input('appFormat', 'app', '应用 Package ID', 'App package ID') + input('appFormat', 'version', '已安装版本', 'Installed version', 'text', T('示例已安装版本：127.0。规则版本必须匹配。', 'Sample installed version: 127.0. Rules must match this version.')) + select('appFormat', 'kind', '内容类型', 'Content type', [['article', T('文章', 'Article')], ['product', T('商品', 'Product')]]) + input('appFormat', 'title', '标题字段（必填）', 'Title selector (required)') + (draft('appFormat').kind === 'article' ? input('appFormat', 'body', '正文字段（必填）', 'Body selector (required)') : input('appFormat', 'itemId', '商品 ID 字段', 'Item ID selector')) + input('appFormat', 'author', '作者字段', 'Author selector') + input('appFormat', 'url', '原网址字段', 'URL selector') + '</div>' + disclosure('app-format-scope', '页面、区域与重复范围', 'Activity, region and repeat scope', input('appFormat', 'activity', 'Activity 名称', 'Activity name') + input('appFormat', 'region', '内容区域', 'Content region') + select('appFormat', 'repeat', '重复项范围', 'Repeated-item scope', [['visible', T('当前可见项', 'Visible items')], ['region', T('指定区域', 'Selected region')]])) + '<div class="actions">' + A('载入匹配的内置规则', 'Load matching built-in rules', 'format-builtin') + A('导入匹配规则', 'Import matching rules', 'format-import') + A('预览字段', 'Preview fields', 'format-preview') + '</div>' + footer('appFormat'), 'settings/native-privacy'); }
  function gatePage() { return frame('文字审查', 'Text review', T('由你指定确切文字，不推断内容意图。', 'You specify exact text; no intent inference.'), '<div class="fields">' + check('gate', 'enabled', '启用文字规则审查', 'Enable text-rule review') + textarea('gate', 'literals', '禁止上传的确切文字（每行一项）', 'Exact forbidden text (one per line)', T('命中规则时丢弃。下面的失败策略只用于审查不完整。', 'Exact matches are discarded. The failure policy below applies only to incomplete review.')) + select('gate', 'failure', '无法完成审查时', 'When review cannot complete', [['hold', T('暂存本机，等待复核', 'Hold locally for review')], ['drop', T('不保存、不上传', 'Drop without saving or sending')], ['allow', T('允许上传', 'Allow sending')]], T('更改策略或关闭审查不会自动放行已有待复核记录。', 'Changing policy or disabling review never automatically releases held records.')) + '</div>' + (android() ? disclosure('privacy-ocr', '用于隐私审查的本机 OCR', 'On-device OCR for privacy review', select('gate', 'ocr', '识别引擎', 'OCR engine', [['chinese_latin', T('中文与拉丁文单引擎', 'Chinese and Latin single engine')], ['latin', T('拉丁文', 'Latin')], ['dual', T('双引擎', 'Dual engine')]]) + textarea('gate', 'engines', '按应用覆盖引擎（JSON）', 'Per-app engine overrides (JSON)') + '<p class="small muted">' + T('只在截图文字规则需要时运行。结果不保存、不上传；完整正文识别由 Central 执行。', 'Runs only when screenshot text rules need it. Results are neither saved nor uploaded; Central performs full recognition.') + '</p>') : '') + footer('gate', L('查看待复核记录', 'Review held records', 'activity/native-review', 'subtle')), 'settings/native-privacy'); }
  function maskSVG(regions) { return '<svg class="ns-mask-preview" viewBox="0 0 400 225" role="img" aria-label="' + T('生成的屏幕遮挡示意', 'Generated screen-mask diagram') + '"><rect width="400" height="225" rx="10" fill="var(--surface)"/><rect x="12" y="12" width="376" height="15" rx="4" fill="var(--line)"/><rect x="12" y="40" width="76" height="170" rx="4" fill="var(--line)"/><path d="M108 55h250 M108 78h210 M108 101h240" stroke="var(--muted)" stroke-width="7" opacity=".3"/>' + regions.map((r, i) => '<rect x="' + r.x * 400 + '" y="' + r.y * 225 + '" width="' + r.width * 400 + '" height="' + r.height * 225 + '" fill="var(--ink)" opacity=".8"/><text x="' + (r.x * 400 + 7) + '" y="' + (r.y * 225 + 17) + '" fill="var(--surface)" font-size="12">' + (i + 1) + '</text>').join('') + '</svg>'; }
  function masksPage() { const rows = draft('masks').regions; return frame('固定遮挡区域', 'Fixed screen masks', T('用生成的示意图调整；不读取你的屏幕。遮挡在 OCR 与保存前生效。', 'Adjust a generated diagram without reading your screen. Masks apply before OCR and persistence.'), '<div id="ns-mask-diagram">' + maskSVG(rows) + '</div><div class="actions">' + A(android() ? '顶部 8%' : '顶部菜单栏', android() ? 'Top 8%' : 'Top menu bar', 'mask-add', 'data-preset="top"') + A(android() ? '底部 12%' : '右上通知区', android() ? 'Bottom 12%' : 'Top-right notifications', 'mask-add', 'data-preset="other"') + A('自定义区域', 'Custom region', 'mask-add', 'data-preset="custom"') + '</div><div class="ns-mask-editors">' + rows.map((r, i) => '<section class="ns-mask-row"><div class="section-head"><strong>' + T('区域 ', 'Region ') + (i + 1) + '</strong>' + A('移除', 'Remove', 'mask-remove', 'data-index="' + i + '"', 'text') + '</div><div class="ns-four">' + (android() ? [['x', 'left', r.x], ['y', 'top', r.y], ['right', 'right', r.x + r.width], ['bottom', 'bottom', r.y + r.height]] : [['x', 'x', r.x], ['y', 'y', r.y], ['width', 'width', r.width], ['height', 'height', r.height]]).map(([k, l, v]) => '<label class="field"><span>' + l + '</span><input class="field-input" type="number" step="0.01" min="0" max="1" value="' + Number(v.toFixed(3)) + '" data-ns-mask="' + i + '" data-coordinate="' + k + '"></label>').join('') + '</div></section>').join('') + '</div><p class="small muted">' + T(android() ? 'Android 使用 left, top, right, bottom；相对画面左上角，范围 0–1。' : 'Mac 使用 x, y, width, height；相对主屏幕左上角，范围 0–1。', android() ? 'Android uses left, top, right, bottom relative to the top-left, normalized to 0–1.' : 'Mac uses x, y, width, height relative to the main-screen top-left, normalized to 0–1.') + '</p>' + footer('masks'), 'settings/native-privacy'); }
  function permissionDefinitions() { return android() ? [['accessibility', '无障碍服务', 'Accessibility', '页面与应用隐私范围', 'Page extraction and app privacy'], ['notifications', '通知使用权', 'Notification access', '通知、媒体与设备事件', 'Notifications, media and device events'], ['usage', '使用情况访问', 'Usage access', '应用活动观测', 'App activity observations'], ['screen', '投屏录制', 'Screen projection', '每次投屏会话单独确认', 'Consent for each projection session'], ['files', '所选文件范围', 'Selected file access', '只访问选择器授予的目录', 'Only directories granted by the picker'], ['calendar', '日历读取', 'Calendar read access', '只读取选定日历', 'Read the selected calendar only']] : [['screen', '屏幕录制', 'Screen recording', '授权后可能需要退出并重新打开采集器', 'May require quitting and reopening the collector'], ['accessibility', '辅助功能', 'Accessibility', '页面字段与通知中心可见内容', 'Page fields and visible Notification Center content'], ['files', '所选文件夹', 'Selected folders', '每个路径单独授予访问', 'Access is granted for each selected path'], ['calendar', '日历读取', 'Calendar read access', '只读权限与日程写入连接分别管理', 'Read permission is separate from calendar write connections']]; }
  function permissionState(id) { const value = S().permissions[id] || (id === 'screen' && state.permission === '已授权' ? 'granted' : 'missing'); return value === 'granted' ? T('已授权', 'Granted') : value === 'denied' ? T('已拒绝', 'Denied') : T('未授权', 'Not granted'); }
  function permissionsPage() { return frame('系统权限', 'System permissions', T('仅在相关任务需要时请求。拒绝后仍可保存本机文字与已选文件。', 'Request permission only for the task that needs it. Denial does not block local notes or already selected files.'), '<div class="ns-permissions">' + permissionDefinitions().map(([id, zh, en, helpZh, helpEn]) => '<article class="ns-permission"><div><h2>' + T(zh, en) + '</h2><p>' + T(helpZh, helpEn) + '</p><strong>' + permissionState(id) + '</strong></div>' + A('打开系统设置示例', 'Open system settings demo', 'permission', 'data-permission="' + id + '"', 'subtle') + '</article>').join('') + '</div>' + (android() ? disclosure('background', '后台运行设置', 'Background operation', '<p>' + T('电池优化、自启动与受限设置由系统和设备厂商控制。返回后保留原任务；不保证所有机型长时间运行。', 'Battery optimization, autostart and restricted settings are controlled by Android and the device vendor. Your task is retained; long-running behavior is not verified on every device.') + '</p><div class="actions">' + A('电池优化', 'Battery optimization', 'background', 'data-kind="battery"') + A('自启动', 'Autostart', 'background', 'data-kind="autostart"') + A('受限设置', 'Restricted settings', 'background', 'data-kind="restricted"') + '</div>') : '') + '<div class="actions ns-related">' + A('刷新权限状态', 'Refresh permission status', 'permission-refresh', '', 'primary') + (S().permissionCaller ? A('返回原任务', 'Return to original task', 'permission-return') : '') + '</div>' + resultHTML('permissions'), 'settings/native-privacy'); }
  function sendingReason() { const n = S(), p = saved('upload'), env = n.environment; if (state.sendPaused) return T('全部发送已暂停', 'All sending is paused'); if (!saved('connection').url) return T('未连接 Central，内容留在本机', 'Central is not connected; content stays local'); if (!env.online) return T('离线，等待连接', 'Offline; waiting for connection'); if (android() && p.wifi && !env.wifi) return T('等待非计费 Wi-Fi', 'Waiting for unmetered Wi-Fi'); if (android() && p.charging && !env.charging) return T('等待充电', 'Waiting for charging'); if (android() && p.battery && env.lowBattery) return T('系统低电量，等待恢复', 'System battery is low'); return ''; }
  function uploadPage() { const d = draft('upload'), n = S(); return frame('发送到 Central', 'Send to Central', T('屏幕、随手记与本机来源共用此策略。暂停采集不会暂停已有队列。', 'Screens, notes and local sources share this policy. Pausing collection does not pause the queue.'), '<div class="ns-status-line"><div><strong>' + (sendingReason() || T('可以发送', 'Ready to send')) + '</strong><small>' + T('目的地：', 'Destination: ') + E(destination()) + '</small></div>' + A(state.sendPaused ? '恢复全部发送' : '暂停全部发送', state.sendPaused ? 'Resume all sending' : 'Pause all sending', 'send-toggle') + '</div><div class="fields">' + select('upload', 'mode', '发送方式', 'Sending mode', [['realtime', T('实时', 'Real time')], ['interval', T('定时', 'Scheduled')], ['batch', T('积攒一批', 'Batch')], ['manual', T('仅手动', 'Manual only')]], T('仅手动不会自动发送；休眠或系统调度可能延迟计划。逐条收到 ACK 后才按保留策略清理本机副本。', 'Manual mode never sends automatically. Sleep and OS scheduling may delay plans. Local cleanup follows per-record acknowledgments and the retention policy.')) + '</div>' + disclosure('upload-advanced', '间隔与打包', 'Intervals and packing', input('upload', 'interval', '间隔 / 最长等待（分钟）', 'Interval / maximum wait (minutes)', 'number', '', 'min="1" max="1440"') + input('upload', 'batch', '每批记录数', 'Records per batch', 'number', '', 'min="1" max="500"') + check('upload', 'packed', '打包上传，逐条确认', 'Pack uploads with per-record acknowledgment') + (android() ? input('upload', 'window', '无图状态 JSONL 合并窗口（分钟）', 'Image-free JSONL window (minutes)', 'number', '', 'min="1" max="1440"') : '')) + (android() ? disclosure('upload-conditions', '网络与电源条件', 'Network and power conditions', check('upload', 'wifi', '仅非计费 Wi-Fi', 'Unmetered Wi-Fi only') + check('upload', 'charging', '仅充电时发送', 'Send only while charging') + check('upload', 'battery', '系统低电量时暂停', 'Pause when system battery is low') + '<p class="small muted">' + T('立即发送与全量补传也遵守已保存的条件。', 'Send now and full reupload also obey saved conditions.') + '</p>') : '') + footer('upload', A('立即发送', 'Send now', 'send-now', '', 'subtle')) + '<div class="ns-menu ns-related">' + menuRow('待发送记录', 'Pending queue', T('按来源与结果查看，接收和处理分别显示', 'Filter by source and outcome; reception and processing are separate'), 'activity/native-queue') + (android() ? menuRow('检查两端与补传', 'Check both ends and reupload', T('仅补传仍保留的本机记录', 'Resend retained local records only'), 'activity/native-reconcile') : menuRow('上传回执与实际内容', 'Receipts and uploaded content', T('查看接收数量、实际字节与原记录', 'Acknowledged counts, actual bytes and original records'), 'activity/native-receipts')) + '</div>' + disclosure('network-demo', '演示连接条件', 'Demo connection conditions', '<div class="actions">' + A(n.environment.online ? '模拟离线' : '恢复网络', n.environment.online ? 'Simulate offline' : 'Restore network', 'environment', 'data-kind="online"') + (android() ? A(n.environment.wifi ? '切为计费网络' : '切为非计费 Wi-Fi', n.environment.wifi ? 'Use metered network' : 'Use unmetered Wi-Fi', 'environment', 'data-kind="wifi"') + A(n.environment.charging ? '模拟未充电' : '模拟充电', n.environment.charging ? 'Simulate unplugged' : 'Simulate charging', 'environment', 'data-kind="charging"') + A(n.environment.lowBattery ? '恢复电量' : '模拟低电量', n.environment.lowBattery ? 'Restore battery' : 'Simulate low battery', 'environment', 'data-kind="lowBattery"') : '') + '</div>')); }
  function queueStatus(status) { return ({ pending: T('本机待发送', 'Pending locally'), received: T('Central 已接收', 'Received by Central'), conflict: T('需要处理冲突', 'Conflict needs attention'), rejected: T('Central 已删除', 'Deleted in Central'), held: T('等待隐私复核', 'Held for privacy review') })[status] || status; }
  function queuePage() { const n = S(), rows = n.queue.filter(r => (n.queueSource === 'all' || r.source === n.queueSource) && (n.queueStatus === 'all' || r.status === n.queueStatus)), pages = Math.max(1, Math.ceil(rows.length / 2)); n.queuePage = Math.min(n.queuePage, pages - 1); return frame('待发送记录', 'Upload queue', T('本机队列与 Central 已接收分别标明。接收不代表已解析或可检索。', 'Local pending and Central received are distinct. Reception does not mean parsed or searchable.'), '<div class="ns-status-line"><span>' + (sendingReason() || T('当前可发送 · 示例速率 0 KiB/s', 'Ready to send · sample rate 0 KiB/s')) + '</span>' + A('立即发送', 'Send now', 'send-now', '', 'primary') + '</div><div class="ns-two"><label class="field"><span>' + T('来源', 'Source') + '</span><select id="ns-queue-source" class="field-input">' + queueSourceOptions().map(([v, l]) => '<option value="' + v + '" ' + (n.queueSource === v ? 'selected' : '') + '>' + l + '</option>').join('') + '</select></label><label class="field"><span>' + T('结果', 'Outcome') + '</span><select id="ns-queue-status" class="field-input">' + ['all', 'pending', 'received', 'conflict', 'rejected'].map(v => '<option value="' + v + '" ' + (n.queueStatus === v ? 'selected' : '') + '>' + (v === 'all' ? T('全部结果', 'All outcomes') : queueStatus(v)) + '</option>').join('') + '</select></label></div>' + (n.queueReadError ? '<div class="notice warn"><div><strong>' + T('暂时无法读取队列', 'Unable to read the queue') + '</strong><p>' + T('数量未知，原记录保留。刷新后重试。', 'Count unknown; originals are retained. Refresh to retry.') + '</p></div></div>' : rows.slice(n.queuePage * 2, n.queuePage * 2 + 2).map(r => '<article class="ns-record"><div><h2>' + E(r.title) + '</h2><p>' + E(r.source) + ' · ' + queueRecordStatus(r) + '</p><small>' + (r.retained ? T('本机原件保留', 'Local original retained') : T('本机原件已清理', 'Local original cleaned')) + '</small></div>' + A('打开记录', 'Open record', 'queue-open', 'data-id="' + r.id + '"', 'subtle') + '</article>').join('') + (!rows.length ? '<p class="ns-empty">' + T('当前筛选没有记录。', 'No records match these filters.') + '</p>' : '')) + '<div class="actions ns-related">' + A('刷新', 'Refresh', 'queue-refresh') + A('上一页', 'Previous', 'queue-page', 'data-delta="-1" ' + (n.queuePage ? '' : 'disabled')) + '<span class="small">' + (n.queuePage + 1) + ' / ' + pages + '</span>' + A('下一页', 'Next', 'queue-page', 'data-delta="1" ' + (n.queuePage < pages - 1 ? '' : 'disabled')) + '</div>' + resultHTML('upload') + disclosure('queue-demo', '演示读取失败', 'Demo read failure', A('模拟无法读取队列', 'Simulate queue read failure', 'queue-error')), 'settings/native-upload'); }
  function reviewPage() { return frame('待复核记录', 'Held records', T('只处理你打开的这一条。更改隐私设置不会放行其他记录。', 'Act on an individual record only. Changing privacy settings never releases other records.'), S().held.map(r => '<article class="ns-record"><div><h2>' + E(r.title) + '</h2><p>' + (r.status === 'held' ? T('审查未完成 · 原记录留在本机', 'Review incomplete · original remains local') : r.status === 'released' ? T('已明确放行，等待发送条件', 'Explicitly released; waiting for sending conditions') : T('已丢弃此记录', 'This record was discarded')) + '</p></div>' + (r.status === 'held' ? A('查看并决定', 'Inspect and decide', 'held-open', 'data-id="' + r.id + '"', 'primary') : '') + '</article>').join('') + resultHTML('held'), 'settings/native-gate'); }
  function receiptsPage() { const n = S(), receipts = n.receipts.length ? n.receipts : [{ id: 'receipt-demo', date: '2026-10-20', count: 1, bytes: 28672, retries: 1, ids: ['local-102'], outcome: 'received', source: 'screen' }]; return frame('上传回执', 'Upload receipts', T('接收数量按 ACK 去重；实际请求字节包括重试。', 'Acknowledged counts are deduplicated; actual request bytes include retries.'), '<div class="ns-two"><label class="field"><span>' + T('日期范围', 'Date range') + '</span><select id="ns-receipt-period" class="field-input"><option value="today">' + T('今天', 'Today') + '</option><option value="week">' + T('最近七天', 'Last seven days') + '</option></select></label><label class="field"><span>' + T('结束日期', 'End date') + '</span><input id="ns-receipt-date" class="field-input" type="date" value="2026-10-20"></label></div><div class="ns-two"><label class="field"><span>' + T('来源', 'Source') + '</span><select id="ns-receipt-source" class="field-input"><option value="all">' + T('全部来源', 'All sources') + '</option><option value="screen">' + T('屏幕', 'Screen') + '</option><option value="folder">' + T('文件夹', 'Folder') + '</option></select></label><label class="field"><span>' + T('结果', 'Outcome') + '</span><select id="ns-receipt-outcome" class="field-input"><option value="all">' + T('全部', 'All') + '</option><option value="received">' + T('已接收', 'Received') + '</option><option value="failed">' + T('失败', 'Failed') + '</option></select></label></div>' + A('查看每日记录', 'Show daily history', 'receipt-filter') + '<div id="ns-receipts-list">' + receiptRows(receipts) + '</div>', 'settings/native-upload'); }
